package com.xirctwerk.vfx.core;
import com.google.gson.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class RenderMaterialTest {
    @TempDir Path directory;
    @Test void allMaterialPresetsValidate(){for(String name:Material.PRESETS)assertFalse(Material.compile(Material.preset(name)).nodes().isEmpty());}
    @Test void everyOperationRoundTrips(){var json=Material.empty();for(String op:Material.OPERATIONS)json.getAsJsonArray("nodes").add(Material.node(op));var material=Material.compile(json);assertEquals(8,material.nodes().size());assertEquals(material,Material.compile(EffectCodec.parseObject(EffectCodec.GSON.toJson(json))));}
    @Test void rejectsCodeAndUnknownOperations(){var json=Material.empty();json.addProperty("shader","void main(){}");assertThrows(EffectCodec.InvalidEffect.class,()->Material.compile(json));json.remove("shader");var node=Material.node("dissolve");node.addProperty("operation","eval");json.getAsJsonArray("nodes").add(node);assertThrows(EffectCodec.InvalidEffect.class,()->Material.compile(json));}
    @Test void rejectsUnboundedAndMalformedValues(){for(String bad:List.of("{\"schemaVersion\":1,\"nodes\":[{\"operation\":\"outline\",\"amount\":2}]}","{\"schemaVersion\":1,\"nodes\":[{\"operation\":\"outline\",\"speed\":\"1\"}]}","{\"schemaVersion\":1,\"nodes\":[{\"operation\":\"outline\",\"enabled\":1}]}","{\"schemaVersion\":1,\"nodes\":[{\"operation\":\"outline\",\"keys\":[{\"time\":0.5,\"value\":1},{\"time\":0.5,\"value\":0}]}]}"))assertThrows(EffectCodec.InvalidEffect.class,()->Material.compile(EffectCodec.parseObject(bad)));var json=Material.empty();for(int i=0;i<17;i++)json.getAsJsonArray("nodes").add(Material.node("outline"));assertThrows(EffectCodec.InvalidEffect.class,()->Material.compile(json));}
    @Test void keyframesInterpolateAndInputsAreImmutable(){var json=Material.empty();var node=Material.node("dissolve");node.add("keys",JsonParser.parseString("[{\"time\":0,\"value\":0},{\"time\":1,\"value\":1}]"));json.getAsJsonArray("nodes").add(node);var compiled=Material.compile(json);assertEquals(.25,compiled.nodes().getFirst().at(.25),1e-9);assertThrows(UnsupportedOperationException.class,()->compiled.nodes().clear());assertThrows(UnsupportedOperationException.class,()->compiled.nodes().getFirst().keys().clear());node.addProperty("amount",0);assertEquals(.5,compiled.nodes().getFirst().amount());}
    @Test void fileRoundTripAndBoundaries()throws Exception{var files=new EffectFiles(directory);var json=Material.empty();files.saveMaterial("test",json);assertEquals(json,files.loadMaterial("test"));assertThrows(java.io.IOException.class,()->files.saveMaterial("../escape",json));assertThrows(java.io.IOException.class,()->files.loadMaterial("../escape"));Files.writeString(directory.resolve("materials/large.json")," ".repeat(65537));assertThrows(java.io.IOException.class,()->files.loadMaterial("large"));Files.writeString(directory.resolve("materials/duplicate.json"),"{\"schemaVersion\":1,\"nodes\":[],\"nodes\":[]}");assertThrows(EffectCodec.InvalidEffect.class,()->files.loadMaterial("duplicate"));}
    @Test void materialSchemaMatchesRuntime()throws Exception{var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(Files.readString(Path.of("../schema/material.schema.json")));var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var json=Material.empty();for(String op:Material.OPERATIONS)json.getAsJsonArray("nodes").add(Material.node(op));assertTrue(schema.validate(mapper.readTree(json.toString())).isEmpty());json.getAsJsonArray("nodes").get(0).getAsJsonObject().addProperty("amount",2);assertFalse(schema.validate(mapper.readTree(json.toString())).isEmpty());}
    @Test void visualChangesRemoveOnlyIncompatibleFieldsAndUndo(){var json=Templates.newProject("visual");var e=Authoring.layer(json,"main");e.addProperty("aspect",2);e.addProperty("alignVelocity",true);e.addProperty("stretch",2);e.add("textureAnimation",JsonParser.parseString("{\"columns\":2,\"rows\":2,\"frames\":4}"));Parameters.expose(json,Set.of("main"),"width","aspect");var project=new Project(json);var before=project.json();project.edit(o->Authoring.changeKind(o,Set.of("main"),"sphere_mesh"));assertEquals("sphere_mesh",project.effect().emitters().getFirst().kind());var mesh=Authoring.layer(project.json(),"main");assertFalse(mesh.has("aspect"));assertFalse(mesh.has("textureAnimation"));assertEquals(e.get("color"),mesh.get("color"));assertTrue(project.undo());assertEquals(before,project.json());}
    @Test void choosingCurrentKindPreservesAuthoredJson(){var json=Templates.newProject("same");Authoring.layer(json,"main").addProperty("pixelSize",1);var before=json.deepCopy();Authoring.changeKind(json,Set.of("main"),"particle");assertEquals(before,json);}
    @Test void meshToSpritePreservesCurvesAndCompatibleBindings(){var json=Templates.newProject("mesh");Authoring.changeKind(json,Set.of("main"),"slash");var e=Authoring.layer(json,"main");e.addProperty("meshScale",2);e.addProperty("pixelSize",4);Parameters.expose(json,Set.of("main"),"extent","meshScale");Parameters.expose(json,Set.of("main"),"power","bloom");var original=e.deepCopy();Authoring.changeKind(json,Set.of("main"),"particle");assertDoesNotThrow(()->EffectCodec.compile(json));assertFalse(e.has("meshScale"));assertFalse(e.has("pixelSize"));assertEquals(original.get("size"),e.get("size"));assertEquals(1,json.getAsJsonArray("parameters").size());assertEquals("power",json.getAsJsonArray("parameters").get(0).getAsJsonObject().get("name").getAsString());}
}
